import rclpy
from rclpy.node import Node


class SafetyMonitorNode(Node):

    def __init__(self):
        super().__init__('safety_monitor_node')

        # -------------------------
        # Declare parameters
        # -------------------------
        self.declare_parameter('robot_speed', 1.0)
        self.declare_parameter('emergency_stop_dist', 1.5)

        # Read initial values
        self.robot_speed = self.get_parameter('robot_speed').value
        self.stop_dist = self.get_parameter('emergency_stop_dist').value

        # Timer to simulate monitoring
        self.timer = self.create_timer(1.0, self.monitor_callback)

        self.get_logger().info("🛡️ Safety Monitor Node started")

        # Enable dynamic updates
        self.add_on_set_parameters_callback(self.parameter_callback)

    # -------------------------
    # Monitoring Logic
    # -------------------------
    def monitor_callback(self):

        # Simulated obstacle distance
        import random
        obstacle_distance = random.uniform(0.5, 3.0)

        self.get_logger().info(
            f"📡 Obstacle distance: {obstacle_distance:.2f} m | "
            f"Speed: {self.robot_speed} | StopDist: {self.stop_dist}"
        )

        if obstacle_distance < self.stop_dist:
            self.get_logger().warn("🚨 TOO CLOSE → STOP ROBOT!")
        else:
            self.get_logger().info("✅ Safe")

    # -------------------------
    # Dynamic Parameter Update
    # -------------------------
    def parameter_callback(self, params):

        for param in params:
            if param.name == 'robot_speed':
                self.robot_speed = param.value
                self.get_logger().info(f"⚡ Updated speed → {self.robot_speed}")

            elif param.name == 'emergency_stop_dist':
                self.stop_dist = param.value
                self.get_logger().info(f"🛑 Updated stop distance → {self.stop_dist}")
        from rcl_interfaces.msg import SetParametersResult

        return SetParametersResult(successful=True)


def main(args=None):
    rclpy.init(args=args)

    node = SafetyMonitorNode()
    rclpy.spin(node)

    node.destroy_node()
    rclpy.shutdown()


if __name__ == '__main__':
    main()